{
  "grammar_topic": "Preposition",
  "sentence_structure": "S + V + Prep + [blank] which S + V.",
  "pattern": "after + relative pronoun (which)",
  "vocabulary": [
    {
      "word": "attendee",
      "meaning": "người tham dự",
      "part_of_speech": "noun"
    },
    {
      "word": "take place",
      "meaning": "diễn ra",
      "part_of_speech": "verb phrase"
    },
    {
      "word": "lecture",
      "meaning": "bài giảng",
      "part_of_speech": "noun"
    },
    {
      "word": "after",
      "meaning": "sau khi",
      "part_of_speech": "preposition"
    }
  ],
  "explanation": "Câu này kiểm tra việc sử dụng giới từ đi trước đại từ quan hệ 'which' để chỉ thời gian hoặc thứ tự sự việc. Bài giảng sẽ diễn ra lúc 6:00 chiều, 'sau' thời điểm đó những người tham dự có thể đặt câu hỏi. Do đó, giới từ 'after' là lựa chọn chính xác về mặt ngữ nghĩa và ngữ cảnh.",
  "distractor_analysis": {
    "A": "across (băng qua, ở bên kia) không phù hợp về ngữ nghĩa để chỉ thời điểm hoặc trình tự diễn ra sự việc sau buổi giảng.",
    "B": "after (sau) là đáp án đúng, kết hợp với mệnh đề quan hệ 'which' (thay thế cho 6:00 P.M. hoặc toàn bộ sự việc trước đó) để chỉ thời gian người tham dự có thể đặt câu hỏi diễn ra sau bài giảng.",
    "C": "inside (bên trong) chỉ vị trí không gian, không phù hợp để kết hợp với mốc thời gian 6:00 P.M. trong ngữ cảnh này.",
    "D": "among (ở giữa, trong số) dùng cho từ ba đối tượng trở lên, không phù hợp để chỉ thời gian hoặc trình tự sự việc."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Word Form / Determiner or Adjective",
  "sentence_structure": "S (The + [blank] + antique shop + in Pepper Valley) + V (will close) + down + Adv (next month).",
  "pattern": "The + [adjective/determiner] + noun + verb",
  "vocabulary": [
    {
      "word": "antique shop",
      "meaning": "cửa hàng đồ cổ",
      "part_of_speech": "noun phrase"
    },
    {
      "word": "close down",
      "meaning": "đóng cửa (hoàn toàn)",
      "part_of_speech": "verb phrase"
    }
  ],
  "explanation": "Câu này yêu cầu điền một từ loại phù hợp vào vị trí trước danh từ 'antique shop' và sau mạo từ 'The'. Từ 'last' trong ngữ cảnh này đóng vai trò là tính từ (mang nghĩa 'cái cuối cùng', 'duy nhất còn lại') để bổ nghĩa cho danh từ 'antique shop'. Cấu trúc 'The last + [noun]' là một cấu trúc hoàn chỉnh và có nghĩa logic trong câu: cửa hàng đồ cổ cuối cùng ở Pepper Valley sẽ đóng cửa vào tháng tới.",
  "distractor_analysis": {
    "A": "last: Đáp án chính xác. 'Last' làm tính từ bổ nghĩa cho danh từ 'antique shop', diễn tả ý nghĩa 'cửa hàng đồ cổ cuối cùng'.",
    "B": "lasts: Sai dạng từ. Đây là động từ chia ở ngôi thứ ba số ít thì hiện tại đơn, không thể đứng trước danh từ để làm định ngữ trong cấu trúc này.",
    "C": "lasted: Sai dạng từ. Đây là dạng quá khứ hoặc quá khứ phân từ của động từ 'last', không phù hợp với vị trí cần tính từ bổ nghĩa cho danh từ.",
    "D": "lasting: Sai về mặt ngữ nghĩa và cấu trúc. 'Lasting' là tính từ mang nghĩa 'lâu dài', nhưng xét về ngữ cảnh 'cửa hàng đồ cổ lâu dài' không tạo ra ý nghĩa hợp lý bằng 'cửa hàng đồ cổ cuối cùng'."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "vocabulary",
  "sentence_structure": "S + will receive + O (an online status [blank]) + Prep + NP.",
  "pattern": "status update",
  "vocabulary": [
    {
      "word": "status",
      "meaning": "tình trạng, trạng thái",
      "part_of_speech": "noun"
    },
    {
      "word": "update",
      "meaning": "bản cập nhật, thông tin mới nhất",
      "part_of_speech": "noun"
    },
    {
      "word": "ongoing",
      "meaning": "đang diễn ra",
      "part_of_speech": "adjective"
    },
    {
      "word": "construction",
      "meaning": "việc xây dựng, công trình",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu hỏi kiểm tra từ vựng phù hợp với ngữ cảnh của câu. Cụm từ 'status update' (bản cập nhật tình hình) là một collocation phổ biến trong tiếng Anh, đặc biệt phù hợp khi nói về việc cư dân nhận được thông tin mới nhất về một dự án xây dựng đang diễn ra.",
  "distractor_analysis": {
    "A": "Đáp án chính xác. 'Status update' tạo thành cụm từ có nghĩa tự nhiên là bản cập nhật tình trạng/tình hình của dự án.",
    "B": "Đáp án sai nghĩa. 'Change' (sự thay đổi) không kết hợp tự nhiên với 'status' trong ngữ cảnh thông báo thông tin dự án này.",
    "C": "Đáp án sai nghĩa. 'Payment' (khoảng thanh toán) không phù hợp với ngữ cảnh nhận thông tin về một dự án xây dựng.",
    "D": "Đáp án sai nghĩa. 'Request' (yêu cầu) không hợp lý khi cư dân 'nhận được' một yêu cầu trực tuyến về tình trạng của dự án xây dựng."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "Pronouns",
  "sentence_structure": "Prep (As a result of) + Pronoun (blank) + Noun (many years) + Participle Phrase (leading media organizations), S (Ms. Ayo) + V (was selected) + Prep (for the Dowel Journalism Prize).",
  "pattern": "As a result of + [possessive adjective] + [noun]",
  "vocabulary": [
    {
      "word": "result",
      "meaning": "kết quả",
      "part_of_speech": "noun"
    },
    {
      "word": "leading",
      "meaning": "dẫn dắt, lãnh đạo",
      "part_of_speech": "adjective"
    },
    {
      "word": "organizations",
      "meaning": "các tổ chức",
      "part_of_speech": "noun"
    },
    {
      "word": "selected",
      "meaning": "được lựa chọn",
      "part_of_speech": "verb"
    }
  ],
  "explanation": "Chỗ trống đứng trước cụm danh từ \"many years leading media organizations\" và theo sau cụm giới từ \"As a result of\". Theo ngữ pháp tiếng Anh, trước một danh từ chỉ sự sở hữu hoặc hành động của ai đó làm chủ thể, ta cần dùng một tính từ sở hữu (possessive adjective). Trong các phương án, \"her\" là tính từ sở hữu bổ nghĩa cho danh từ \"years\", phù hợp về cả ngữ pháp lẫn ngữ nghĩa.",
  "distractor_analysis": {
    "A": "Đại từ nhân xưng chủ ngữ (she) không thể đứng trước cụm danh từ để làm từ hạn định.",
    "B": "Đáp án chính xác. Tính từ sở hữu \"her\" đứng trước danh từ \"many years\" để chỉ khoảng thời gian nhiều năm cô ấy dẫn dắt các tổ chức truyền thông.",
    "C": "Đại từ sở hữu (hers) thay thế cho một danh từ đã được nhắc tới trước đó, không đứng trước danh từ \"many years\" trong trường hợp này.",
    "D": "Đại từ phản thân (herself) dùng để nhấn mạnh hoặc khi chủ ngữ và tân ngữ trùng nhau, không phù hợp để làm từ hạn định trước danh từ."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "Noun Collocation / Vocabulary",
  "sentence_structure": "To (Prep) stop (V) the (Det) [BLANK] (N) of (Prep) computer (N) viruses (N), do (V) not (Adv) open (V) suspicious (Adj) e-mails (N).",
  "pattern": "stop the + [noun] + of + [noun]",
  "vocabulary": [
    {
      "word": "spread",
      "meaning": "sự lây lan",
      "part_of_speech": "noun"
    },
    {
      "word": "suspicious",
      "meaning": "đáng ngờ",
      "part_of_speech": "adjective"
    },
    {
      "word": "virus",
      "meaning": "vi-rút",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu này kiểm tra khả năng kết hợp từ (collocation) và ý nghĩa từ vựng. Danh từ 'spread' (sự lây lan) kết hợp hoàn hảo với cụm từ 'of computer viruses' (của vi-rút máy tính) để tạo thành ý nghĩa hợp lý: 'Để ngăn chặn sự lây lan của vi-rút máy tính, đừng mở các email đáng ngờ.'",
  "distractor_analysis": {
    "A": "Sai về mặt ngữ nghĩa và kết hợp từ. 'Break' không tạo thành cụm từ tự nhiên với 'of computer viruses' trong ngữ cảnh ngăn chặn.",
    "B": "Đáp án chính xác. 'Spread' (sự lây lan) phù hợp về mặt ngữ nghĩa với việc ngăn chặn sự lan rộng của vi-rút máy tính.",
    "C": "Sai về mặt ngữ nghĩa. 'Balance' (sự cân bằng) không phù hợp với ngữ cảnh ngăn chặn vi-rút.",
    "D": "Sai về mặt ngữ nghĩa. 'Surface' (bề mặt) không tạo thành cụm từ hợp lý với ngữ cảnh bảo mật máy tính."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Word Form",
  "sentence_structure": "S + Adv + V + O",
  "pattern": "Adverb + Verb (considered)",
  "vocabulary": [
    {
      "word": "hiring manager",
      "meaning": "người quản lý tuyển dụng",
      "part_of_speech": "noun phrase"
    },
    {
      "word": "applicant",
      "meaning": "ứng viên",
      "part_of_speech": "noun"
    },
    {
      "word": "résumé",
      "meaning": "sơ yếu lý lịch, hồ sơ xin việc",
      "part_of_speech": "noun"
    },
    {
      "word": "qualification",
      "meaning": "trình độ chuyên môn, năng lực",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu này thiếu một trạng từ để bổ nghĩa cho động từ chính \"considered\". Vị trí trống nằm giữa chủ ngữ \"The hiring manager\" và động từ \"considered\", do đó ta cần dùng trạng từ (adverb) để diễn tả cách thức hành động diễn ra. Đáp án (C) \"carefully\" là trạng từ phù hợp nhất về mặt ngữ pháp và ngữ nghĩa.",
  "distractor_analysis": {
    "A": "\"caring\" là tính từ (hoặc phân từ hiện tại), không phù hợp vì đứng trước động từ chính để bổ nghĩa cho động từ thì cần trạng từ chứ không phải tính từ.",
    "B": "\"careful\" là tính từ, không thể đứng ở vị trí này để bổ nghĩa cho động từ \"considered\".",
    "C": "\"carefully\" là trạng từ, đứng trước động từ \"considered\" để bổ nghĩa cho hành động xem xét một cách cẩn thận, đáp án chính xác.",
    "D": "\"carefulness\" là danh từ, không phù hợp với cấu trúc vị trí cần trạng từ bổ nghĩa cho động từ trong câu."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "conjunction",
  "sentence_structure": "S + V + Prep Phrase + and + V + O",
  "pattern": "V1 + and + V2 (coordinate verbs sharing the same subject)",
  "vocabulary": [
    {
      "word": "leave",
      "meaning": "rời đi, lên đường",
      "part_of_speech": "verb"
    },
    {
      "word": "oversee",
      "meaning": "giám sát",
      "part_of_speech": "verb"
    },
    {
      "word": "opening",
      "meaning": "lễ khai trương, sự mở cửa",
      "part_of_speech": "noun"
    },
    {
      "word": "branch",
      "meaning": "chi nhánh",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu này yêu cầu một liên từ hoặc liên kết từ để nối liền hai hành động của cùng một chủ ngữ 'Mr. Sakamoto' (sẽ rời đi và sẽ giám sát). Liên từ 'and' (C) đóng vai trò là liên từ đẳng lập dùng để nối hai động từ 'will leave' và 'will oversee', diễn tả hai hành động diễn ra tuần tự do cùng một chủ ngữ thực hiện.",
  "distractor_analysis": {
    "A": "because là liên từ chỉ nguyên nhân, không phù hợp về ngữ nghĩa vì việc giám sát chi nhánh không phải là nguyên nhân của chuyến đi mà là một hành động tiếp theo được lên kế hoạch.",
    "B": "in addition là trạng từ/trạng từ liên kết, thường cần dấu phẩy hoặc cấu trúc khác để nối mệnh đề, không thể nối trực tiếp hai động từ mà không có chủ ngữ hoặc dấu câu phù hợp.",
    "C": "and là liên từ đẳng lập chính xác để nối liền hai hành động (will leave và will oversee) do cùng một chủ ngữ thực hiện trong câu.",
    "D": "prior to là giới từ mang nghĩa 'trước khi', theo sau phải là danh từ hoặc danh động từ (gerund), không thể đứng trước một động từ chia thì tương lai 'will oversee'."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "Noun Compound / Noun Form",
  "sentence_structure": "S (Tarateer Pharmaceuticals) + V (is varying) + O (its product _____).",
  "pattern": "possessive determiner (its) + noun modifier (product) + head noun (line)",
  "vocabulary": [
    {
      "word": "varying",
      "meaning": "đang làm thay đổi, đa dạng hóa",
      "part_of_speech": "verb"
    },
    {
      "word": "product",
      "meaning": "sản phẩm",
      "part_of_speech": "noun"
    },
    {
      "word": "line",
      "meaning": "dòng sản phẩm",
      "part_of_speech": "noun"
    },
    {
      "word": "medications",
      "meaning": "dược phẩm, thuốc",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu này kiểm tra việc lựa chọn danh từ chính để tạo thành cụm danh từ ghép 'product line' (dòng sản phẩm). Phía trước chỗ trống có tính từ sở hữu 'its' và danh từ 'product' đóng vai trò bổ nghĩa, do đó chỗ trống cần một danh từ đếm được ở số ít (hoặc danh từ chính) để hoàn thành cụm danh từ 'product line'. Đáp án 'line' (danh từ) là lựa chọn chính xác về mặt ngữ pháp và ngữ nghĩa.",
  "distractor_analysis": {
    "A": "Sai cấu trúc ngữ pháp vì cụm 'to line' (động từ nguyên mẫu có 'to') không phù hợp đứng sau cụm danh từ 'its product' để làm tân ngữ cho động từ 'varying'.",
    "B": "Sai dạng từ vì 'lining' là dạng danh động từ (gerund) hoặc hiện tại phân từ (present participle), không phù hợp để tạo thành cụm danh từ ghép chỉ dòng sản phẩm.",
    "C": "Sai dạng từ vì 'lined' là quá khứ phân từ hoặc tính từ, không tạo thành cụm danh từ chính xác đứng sau 'product'.",
    "D": "Là đáp án chính xác. 'line' là danh từ, kết hợp với 'product' tạo thành cụm danh từ 'product line' (dòng sản phẩm) rất phổ biến trong kinh doanh."
  },
  "difficulty": "medium"
}

{
  "grammar_topic": "verb tense",
  "sentence_structure": "S + V + O",
  "pattern": "Subject (Dynart, Inc.) + Adverb (continuously) + Verb (seeks) + Object (new ways)",
  "vocabulary": [
    {
      "word": "continuously",
      "meaning": " liên tục, liên tiếp",
      "part_of_speech": "adverb"
    },
    {
      "word": "reduce",
      "meaning": "giảm bớt",
      "part_of_speech": "verb"
    },
    {
      "word": "plastics",
      "meaning": "chất nhựa, đồ nhựa",
      "part_of_speech": "noun"
    }
  ],
  "explanation": "Câu này thiếu động từ chính cho chủ ngữ số ít 'Dynart, Inc.'. Trạng từ 'continuously' đứng trước vị trí trống để bổ nghĩa cho động từ chính. Do đó, ta cần một dạng động từ chia ở thì hiện tại đơn với chủ ngữ ngôi thứ ba số ít. Đáp án 'seeks' (động từ chia ở số ít) là phù hợp nhất.",
  "distractor_analysis": {
    "A": "Là động từ chia ở thì hiện tại đơn dạng số ít (thêm -s), phù hợp với chủ ngữ số ít 'Dynart, Inc.' và trạng từ chỉ tần suất 'continuously'.",
    "B": "Là danh từ chỉ người ('người tìm kiếm'), không phù hợp về mặt cấu trúc ngữ pháp vì câu đang thiếu động từ chính.",
    "C": "Là động từ nguyên mẫu có 'to', không thể đóng vai trò là động từ chính của câu độc lập trong trường hợp này.",
    "D": "Là phân từ hiện tại/ danh động từ (-ing), không thể đứng một mình làm động từ chính của chủ ngữ 'Dynart, Inc.' nếu không có trợ động từ đi kèm."
  },
  "difficulty": "easy"
}

{
  "grammar_topic": "Word Form",
  "sentence_structure": "S + V + O",
  "pattern": "Plural Subject (The cash registers) + Adverb (automatically) + Verb (blank) + Object (the remaining inventory)",
  "vocabulary": [
    {
      "word": "cash register",
      "meaning": "máy tính tiền",
      "part_of_speech": "noun phrase"
    },
    {
      "word": "automatically",
      "meaning": "tự động",
      "part_of_speech": "adverb"
    },
    {
      "word": "inventory",
      "meaning": "hàng tồn kho, kiểm kê",
      "part_of_speech": "noun"
    }
  ],
